namespace BlazorNotifications.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();
    private static readonly string[] SampleMessages =
    [
        "Your deployment completed successfully.",
        "New comment on your pull request.",
        "Build failed for branch 'feature/auth'.",
        "You were mentioned in a discussion.",
        "Server CPU usage exceeded 90%.",
        "Backup completed for database 'prod'.",
        "New team member joined the project.",
        "Security scan found 0 vulnerabilities.",
        "Release v2.4.1 is ready for review.",
        "Disk space warning on node-3.",
    ];

    public NotificationService()
    {
        // Seed with a few initial notifications.
        for (var i = 0; i < 3; i++)
        {
            _notifications.Add(new Notification(
                _nextId++,
                SampleMessages[i],
                DateTime.UtcNow.AddMinutes(-(3 - i))));
        }
    }

    /// <summary>Returns all notifications currently stored.</summary>
    public List<Notification> GetAll()
    {
        lock (_lock) return [.. _notifications];
    }

    /// <summary>Returns only notifications with an Id greater than <paramref name="sinceId"/>.</summary>
    public List<Notification> GetSince(int sinceId)
    {
        lock (_lock) return _notifications.Where(n => n.Id > sinceId).ToList();
    }

    /// <summary>
    /// Simulates an external system pushing a new notification at random intervals.
    /// Called by the background hosted service.
    /// </summary>
    public Notification Add()
    {
        lock (_lock)
        {
            var msg = SampleMessages[_nextId % SampleMessages.Length];
            var n = new Notification(_nextId++, msg, DateTime.UtcNow);
            _notifications.Add(n);
            return n;
        }
    }
}

namespace BlazorNotifications.Services;

/// <summary>
/// Background hosted service that periodically adds a fake notification
/// so there is something new to discover when the page polls.
/// </summary>
public class NotificationProducerService(NotificationService notifications) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(7), stoppingToken);
            notifications.Add();
        }
    }
}

@page "/notifications"
@rendermode @(new InteractiveServerRenderMode(prerender: true))
@implements IDisposable
@inject BlazorNotifications.Services.NotificationService NotificationSvc

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@notifications.Count</span>
</h1>

@if (notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group mt-3">
        @foreach (var n in notifications.OrderByDescending(n => n.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted ms-3 text-nowrap">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<BlazorNotifications.Services.Notification> notifications = [];
    private CancellationTokenSource? _cts;
    private int _lastSeenId;

    // Runs during prerender AND when the component becomes interactive.
    // PersistentComponentState is one option to avoid the double-fetch,
    // but a simpler approach: just load once; OnAfterRenderAsync only
    // starts polling — it never re-fetches the initial set.
    protected override void OnInitialized()
    {
        notifications = NotificationSvc.GetAll();
        _lastSeenId = notifications.Count > 0 ? notifications.Max(n => n.Id) : 0;
    }

    // Called only on the client (never during static SSR prerender).
    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (!firstRender) return;

        _cts = new CancellationTokenSource();
        var token = _cts.Token;

        _ = Task.Run(async () =>
        {
            while (!token.IsCancellationRequested)
            {
                await Task.Delay(TimeSpan.FromSeconds(5), token);

                var newer = NotificationSvc.GetSince(_lastSeenId);
                if (newer.Count > 0)
                {
                    notifications.AddRange(newer);
                    _lastSeenId = newer.Max(n => n.Id);
                    await InvokeAsync(StateHasChanged);
                }
            }
        }, token);
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

